CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL, issuer TEXT NOT NULL, provider_ref TEXT, cardholder_ref TEXT, last4 TEXT NOT NULL, exp_month INTEGER NOT NULL, exp_year INTEGER NOT NULL, limit_amount REAL NOT NULL, currency TEXT NOT NULL, allowed_merchants TEXT NOT NULL DEFAULT '[]', allowed_mccs TEXT NOT NULL DEFAULT '[]', supplier_id TEXT, po_id TEXT, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, label TEXT NOT NULL, created_by TEXT NOT NULL, approved_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cards_tenant ON cards (tenant_id, created_at);
CREATE TABLE IF NOT EXISTS card_authorizations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, card_id TEXT NOT NULL, merchant TEXT NOT NULL, mcc TEXT, amount REAL NOT NULL, currency TEXT NOT NULL, approved INTEGER NOT NULL, reason TEXT, status TEXT NOT NULL, captured_amount REAL NOT NULL DEFAULT 0, journal_id TEXT, provider_ref TEXT, source TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS card_auth_card ON card_authorizations (card_id, created_at);
CREATE INDEX IF NOT EXISTS card_auth_tenant ON card_authorizations (tenant_id, created_at);
